CREATE TYPE "MessageChannel" AS ENUM ('SMS','WHATSAPP','EMAIL');
CREATE TYPE "MessageCampaignStatus" AS ENUM ('DRAFT','READY','CANCELLED');
CREATE TYPE "MessageDeliveryStatus" AS ENUM ('NOT_SENT','QUEUED','SENT','DELIVERED','FAILED');
CREATE TYPE "MessageConsentStatus" AS ENUM ('UNKNOWN','OPTED_IN','OPTED_OUT');
CREATE TABLE "MessageTemplate" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"name" VARCHAR(120) NOT NULL,"channel" "MessageChannel" NOT NULL,"body" VARCHAR(5000) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MessageTemplate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MessageCampaign" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"templateId" TEXT,"name" VARCHAR(160) NOT NULL,"channel" "MessageChannel" NOT NULL,"status" "MessageCampaignStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MessageCampaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MessageRecipient" ("id" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"guestId" TEXT,"contributorId" TEXT,"destination" VARCHAR(254) NOT NULL,"renderedBody" VARCHAR(5000) NOT NULL,"status" "MessageDeliveryStatus" NOT NULL DEFAULT 'NOT_SENT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MessageRecipient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MessageLog" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"recipientId" TEXT,"channel" "MessageChannel" NOT NULL,"status" "MessageDeliveryStatus" NOT NULL,"errorMessage" VARCHAR(500),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"sentAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),CONSTRAINT "MessageLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MessageConsent" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"guestId" TEXT,"contributorId" TEXT,"channel" "MessageChannel" NOT NULL,"status" "MessageConsentStatus" NOT NULL DEFAULT 'UNKNOWN',"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MessageConsent_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MessageTemplate_eventId_channel_idx" ON "MessageTemplate"("eventId","channel"); CREATE INDEX "MessageCampaign_eventId_status_createdAt_idx" ON "MessageCampaign"("eventId","status","createdAt"); CREATE UNIQUE INDEX "MessageRecipient_campaignId_destination_key" ON "MessageRecipient"("campaignId","destination"); CREATE INDEX "MessageRecipient_campaignId_status_idx" ON "MessageRecipient"("campaignId","status"); CREATE INDEX "MessageLog_eventId_createdAt_idx" ON "MessageLog"("eventId","createdAt"); CREATE INDEX "MessageLog_campaignId_status_idx" ON "MessageLog"("campaignId","status"); CREATE UNIQUE INDEX "MessageConsent_eventId_guestId_contributorId_channel_key" ON "MessageConsent"("eventId","guestId","contributorId","channel"); CREATE INDEX "MessageConsent_eventId_channel_status_idx" ON "MessageConsent"("eventId","channel","status");
ALTER TABLE "MessageTemplate" ADD CONSTRAINT "MessageTemplate_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MessageCampaign" ADD CONSTRAINT "MessageCampaign_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MessageCampaign" ADD CONSTRAINT "MessageCampaign_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "MessageTemplate"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "MessageRecipient" ADD CONSTRAINT "MessageRecipient_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "MessageCampaign"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MessageRecipient" ADD CONSTRAINT "MessageRecipient_guestId_fkey" FOREIGN KEY ("guestId") REFERENCES "Guest"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "MessageRecipient" ADD CONSTRAINT "MessageRecipient_contributorId_fkey" FOREIGN KEY ("contributorId") REFERENCES "EventContributor"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "MessageLog" ADD CONSTRAINT "MessageLog_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MessageLog" ADD CONSTRAINT "MessageLog_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "MessageCampaign"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MessageLog" ADD CONSTRAINT "MessageLog_recipientId_fkey" FOREIGN KEY ("recipientId") REFERENCES "MessageRecipient"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "MessageConsent" ADD CONSTRAINT "MessageConsent_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MessageConsent" ADD CONSTRAINT "MessageConsent_guestId_fkey" FOREIGN KEY ("guestId") REFERENCES "Guest"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "MessageConsent" ADD CONSTRAINT "MessageConsent_contributorId_fkey" FOREIGN KEY ("contributorId") REFERENCES "EventContributor"("id") ON DELETE SET NULL ON UPDATE CASCADE;
